/-- For [the specified mathematical inputs](hyp:g,r), [this definition](goal) introduces the corresponding object. -/
def cell (g : ScoreSpace ε → LabelSpace J) (r : LabelSpace J) : Set (ScoreSpace ε) :=
  {e | g e = r} -- @realizes C(release cell)

/-- For [the specified mathematical inputs](hyp:ε,J,H,g,a,r), [this definition](goal) introduces the corresponding object. -/
def cellAbsoluteDeviation {ε : ℝ} {J : ℕ}
    (H : Measure (ScoreSpace ε)) (g : ScoreSpace ε → LabelSpace J)
    (a : ArmSpace) (r : LabelSpace J) : ℝ :=
  sInf {v : ℝ | ∃ c ∈ Set.Icc ((1 - ε)⁻¹) ε⁻¹,
    v = ∫ e in cell g r, |1 - c * armProb a e| ∂H}

/-- For [the specified mathematical inputs](hyp:y), [this definition](goal) introduces the corresponding object. -/
def clampOutcome (y : ℝ) : OutcomeSpace :=
  ⟨min 1 (max 0 y), by constructor <;> simp⟩

